PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  ?film rdfs:label ?filmLabel .
  FILTER(langMatches(lang(?filmLabel),"EN") && (regex(str(?filmLabel), "Before the Bat", "i") || regex(str(?filmLabel), "Agar Tum Na Hote", "i")))
  OPTIONAL { ?film dbo:director ?director . }
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
  OPTIONAL { ?director dbp:birthDate ?birthDate . }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel),"EN")) }
}

